//! Replays `testdata/port/ingest/notion-report.json`, generated by the real Go
//! `TestPortNotionReportContract`: `BuildMigrationReport` and
//! `WriteMigrationReport` with fixed timestamps (UTC, nanoseconds, non-UTC
//! offset, zero), HTML-escaped warnings and nil/populated results. The exact
//! bytes of every written report, and the unwritable-path error, must match.
#![cfg(unix)]

use serde::Deserialize;
use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use symdesk_ingest::notion::{PageResult, Stats, write_migration_report};
use time::OffsetDateTime;
use time::format_description::well_known::Rfc3339;

#[derive(Deserialize, Clone)]
struct Input {
    imported: usize,
    skipped: usize,
    failed: usize,
    total: usize,
    warnings: Option<Vec<String>>,
    run_id: String,
    source: String,
    mode: String,
    started_at: String,
    finished_at: String,
    results: Option<Vec<PageResult>>,
}

#[derive(Deserialize, Clone)]
struct Case {
    id: String,
    stats: Input,
    dry_run: bool,
    written: String,
    error: String,
}

#[derive(Deserialize)]
struct Fixture {
    schema_version: u32,
    cases: Vec<Case>,
}

fn parse(s: &str) -> Option<OffsetDateTime> {
    (!s.is_empty()).then(|| OffsetDateTime::parse(s, &Rfc3339).unwrap())
}

fn render(case: &Case, dir: &Path) -> (String, String) {
    let i = &case.stats;
    let stats = Stats {
        imported: i.imported,
        skipped: i.skipped,
        failed: i.failed,
        total: i.total,
        warnings: i.warnings.clone().unwrap_or_default(),
        run_id: i.run_id.clone(),
        source: i.source.clone(),
        mode: i.mode.clone(),
        started_at: parse(&i.started_at),
        finished_at: parse(&i.finished_at),
        results: i.results.clone().unwrap_or_default(),
    };
    let path = if case.id == "unwritable-directory" {
        dir.join("missing-dir/x.json")
    } else {
        dir.join(format!("{}.json", case.id))
    };
    let outcome = write_migration_report(
        path.to_str().unwrap(),
        &stats.build_migration_report(case.dry_run),
    );
    match outcome {
        Ok(()) => {
            let mode = std::fs::metadata(&path).unwrap().permissions().mode() & 0o777;
            assert_eq!(mode, 0o600, "{}: report mode", case.id);
            (std::fs::read_to_string(&path).unwrap(), String::new())
        }
        Err(e) => (String::new(), e.replace(dir.to_str().unwrap(), "$DIR")),
    }
}

fn fixture() -> Fixture {
    let f: Fixture = serde_json::from_slice(
        &std::fs::read(
            Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("../../testdata/port/ingest/notion-report.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(f.schema_version, 1);
    f
}

#[test]
fn notion_reports_match_go_bytes() {
    let fx = fixture();
    assert!(fx.cases.len() >= 7);
    let dir = std::env::temp_dir().join(format!("notion-report-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let dir = std::fs::canonicalize(&dir).unwrap();
    let mut bad = Vec::new();
    for case in &fx.cases {
        let (written, error) = render(case, &dir);
        if written != case.written || error != case.error {
            bad.push(format!(
                "{}:\n go   {:?} / {:?}\n rust {:?} / {:?}",
                case.id, case.written, case.error, written, error
            ));
        }
    }
    let _ = std::fs::remove_dir_all(&dir);
    assert!(bad.is_empty(), "{}", bad.join("\n"));
}

#[test]
fn notion_report_negative_controls_are_caught() {
    let fx = fixture();
    let dir = std::env::temp_dir().join(format!("notion-report-neg-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let dir = std::fs::canonicalize(&dir).unwrap();
    let case = fx.cases.iter().find(|c| c.id == "mixed-results").unwrap();
    let (written, _) = render(case, &dir);
    assert_eq!(written, case.written);
    assert!(written.contains("\\u003cx\\u003e") && written.contains("\"duration_seconds\": 2.5"));
    let mut tampered = case.clone();
    tampered.stats.imported += 1;
    assert_ne!(render(&tampered, &dir).0, case.written);
    let mut tampered = case.clone();
    tampered.stats.warnings = Some(vec!["html <b>".into()]);
    assert_ne!(render(&tampered, &dir).0, case.written);
    let _ = std::fs::remove_dir_all(&dir);
}
